import fs from 'fs';
import path from 'path';
import type { VariantAssignedWorkspace } from './contracts';
import { AgentVariantsError } from './errors';
import { isPathWithinRoot } from '../utils/pathContainment';
import { cloneOrCopyDirSync } from '../utils/cloneOrCopyDirSync';

type ArtifactWorkspaceRecord = Extract<
  VariantAssignedWorkspace,
  { kind: 'artifact_directory' }
> & {
  workItemId: string;
  allowedRoot: string;
};

type GitWorkspaceRecord = Extract<
  VariantAssignedWorkspace,
  { kind: 'git_worktree' }
> & {
  workItemId: string;
};

type VariantWorkspaceRecord = ArtifactWorkspaceRecord | GitWorkspaceRecord;

export type AssignArtifactWorkspaceInput = {
  workItemId: string;
  rootPath: string;
  allowedRoot: string;
  entryPath: string;
  sourceDirectory?: string;
  seedHtml?: string;
};

export class VariantWorkspaceManager {
  private readonly records = new Map<string, VariantWorkspaceRecord>();

  registerGitWorkspace(args: {
    workItemId: string;
    rootPath: string;
    projectPath: string;
  }): void {
    const existing = this.records.get(args.workItemId);
    if (existing?.kind === 'artifact_directory') {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Cannot replace artifact workspace ${args.workItemId} with a git workspace`,
      );
    }
    this.records.set(args.workItemId, {
      kind: 'git_worktree',
      workItemId: args.workItemId,
      rootPath: args.rootPath,
      projectPath: args.projectPath,
    });
  }

  assignArtifactWorkspace(args: AssignArtifactWorkspaceInput): void {
    const existing = this.records.get(args.workItemId);
    if (existing?.kind === 'git_worktree') {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Cannot replace git workspace ${args.workItemId} with an artifact workspace`,
      );
    }
    fs.mkdirSync(args.allowedRoot, { recursive: true });
    const allowedRoot = fs.realpathSync(args.allowedRoot);
    const requestedRelativePath = path.relative(
      path.resolve(args.allowedRoot),
      path.resolve(args.rootPath),
    );
    const requestedRoot = path.resolve(allowedRoot, requestedRelativePath);
    if (
      requestedRoot === allowedRoot ||
      !isPathWithinRoot(allowedRoot, requestedRoot)
    ) {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Assigned artifact workspace escapes its allowed root for ${args.workItemId}`,
      );
    }

    fs.rmSync(requestedRoot, { recursive: true, force: true });
    if (args.sourceDirectory && fs.existsSync(args.sourceDirectory)) {
      cloneOrCopyDirSync(args.sourceDirectory, requestedRoot);
    } else {
      fs.mkdirSync(requestedRoot, { recursive: true });
    }

    const rootPath = fs.realpathSync(requestedRoot);
    if (!isPathWithinRoot(allowedRoot, rootPath)) {
      fs.rmSync(requestedRoot, { recursive: true, force: true });
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Assigned artifact workspace resolves outside its allowed root for ${args.workItemId}`,
      );
    }
    const entryFile = path.resolve(rootPath, args.entryPath);
    if (!isPathWithinRoot(rootPath, entryFile)) {
      fs.rmSync(rootPath, { recursive: true, force: true });
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Assigned artifact entry escapes its workspace for ${args.workItemId}`,
      );
    }
    if (!fs.existsSync(entryFile)) {
      fs.mkdirSync(path.dirname(entryFile), { recursive: true });
      if (args.seedHtml) {
        fs.writeFileSync(entryFile, args.seedHtml, 'utf8');
      }
    }

    this.records.set(args.workItemId, {
      kind: 'artifact_directory',
      workItemId: args.workItemId,
      rootPath,
      entryPath: args.entryPath,
      allowedRoot,
    });
  }

  getAssignedWorkspace(
    workItemId: string,
  ): VariantAssignedWorkspace | undefined {
    const record = this.records.get(workItemId);
    if (!record) return undefined;
    if (record.kind === 'git_worktree') {
      return {
        kind: record.kind,
        rootPath: record.rootPath,
        projectPath: record.projectPath,
      };
    }
    return {
      kind: record.kind,
      rootPath: record.rootPath,
      entryPath: record.entryPath,
    };
  }

  readArtifact(workItemId: string): { html: string; assetBase: string } {
    const record = this.requireArtifactWorkspace(workItemId);
    let rootStat: fs.Stats;
    let resolvedRoot: string;
    try {
      rootStat = fs.lstatSync(record.rootPath);
      resolvedRoot = fs.realpathSync(record.rootPath);
    } catch {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Assigned artifact workspace is missing for ${workItemId}`,
      );
    }
    if (
      rootStat.isSymbolicLink() ||
      !rootStat.isDirectory() ||
      resolvedRoot === record.allowedRoot ||
      !isPathWithinRoot(record.allowedRoot, resolvedRoot)
    ) {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Assigned artifact workspace escapes its allowed root for ${workItemId}`,
      );
    }

    const entryFile = path.resolve(resolvedRoot, record.entryPath);
    if (!isPathWithinRoot(resolvedRoot, entryFile)) {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Assigned artifact entry escapes its workspace for ${workItemId}`,
      );
    }
    let entryStat: fs.Stats;
    let resolvedEntry: string;
    try {
      entryStat = fs.lstatSync(entryFile);
      resolvedEntry = fs.realpathSync(entryFile);
    } catch {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Assigned artifact entry ${record.entryPath} is missing for ${workItemId}`,
      );
    }
    if (
      entryStat.isSymbolicLink() ||
      !entryStat.isFile() ||
      entryStat.nlink !== 1 ||
      !isPathWithinRoot(resolvedRoot, resolvedEntry)
    ) {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Assigned artifact entry is not a safe file for ${workItemId}`,
      );
    }

    const html = fs.readFileSync(resolvedEntry, 'utf8');
    if (html.trim().length === 0) {
      throw new AgentVariantsError(
        'SCHEMA_VALIDATION_FAILED',
        `Assigned artifact entry ${record.entryPath} is empty for ${workItemId}`,
      );
    }
    return { html, assetBase: resolvedRoot };
  }

  promoteArtifactWorkspace(args: {
    sourceWorkItemId: string;
    targetWorkItemId: string;
  }): void {
    const source = this.requireArtifactWorkspace(args.sourceWorkItemId);
    const target = this.records.get(args.targetWorkItemId);
    if (target?.kind === 'git_worktree') {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Cannot promote an artifact over git workspace ${args.targetWorkItemId}`,
      );
    }
    if (
      target?.kind === 'artifact_directory' &&
      target.rootPath !== source.rootPath
    ) {
      this.removeArtifactWorkspace(args.targetWorkItemId);
    }
    this.records.delete(args.sourceWorkItemId);
    this.records.set(args.targetWorkItemId, {
      ...source,
      workItemId: args.targetWorkItemId,
    });
  }

  removeArtifactWorkspace(workItemId: string): void {
    const record = this.records.get(workItemId);
    if (record?.kind !== 'artifact_directory') return;
    this.removeArtifactDirectory(record);
    this.records.delete(workItemId);
  }

  getOwnedArtifactRoots(): string[] {
    return [
      ...new Set(
        [...this.records.values()]
          .filter(
            (record): record is ArtifactWorkspaceRecord =>
              record.kind === 'artifact_directory',
          )
          .map((record) => record.rootPath),
      ),
    ];
  }

  removeOwnedArtifactWorkspaces(): void {
    const artifactWorkItemIds = [...this.records.values()]
      .filter(
        (record): record is ArtifactWorkspaceRecord =>
          record.kind === 'artifact_directory',
      )
      .map((record) => record.workItemId);
    artifactWorkItemIds.forEach((workItemId) => {
      this.removeArtifactWorkspace(workItemId);
    });
  }

  private requireArtifactWorkspace(
    workItemId: string,
  ): ArtifactWorkspaceRecord {
    const record = this.records.get(workItemId);
    if (record?.kind !== 'artifact_directory') {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `No assigned artifact workspace exists for ${workItemId}`,
      );
    }
    return record;
  }

  private removeArtifactDirectory(record: ArtifactWorkspaceRecord): void {
    let rootStat: fs.Stats;
    let resolvedRoot: string;
    try {
      rootStat = fs.lstatSync(record.rootPath);
      resolvedRoot = fs.realpathSync(record.rootPath);
    } catch {
      return;
    }
    if (
      rootStat.isSymbolicLink() ||
      resolvedRoot === record.allowedRoot ||
      !isPathWithinRoot(record.allowedRoot, resolvedRoot)
    ) {
      return;
    }
    fs.rmSync(resolvedRoot, { recursive: true, force: true });
  }
}
